class Schueler:
    schule = "HTL"

    def __init__(self, name, klasse):
        self.name = name
        self.klasse = klasse

    def gruss(self):
        return f"Hallo, {self.name}!"

s = Schueler("Ana", "4AHIF")
print(type(s).__name__)   # Schueler
print(isinstance(s, Schueler))  # True
print(vars(s))
# {'name': 'Ana', 'klasse': '4AHIF'}
print([a for a in dir(s)
       if not a.startswith("_")])
# ['gruss', 'klasse', 'name', 'schule']

class Befehle:
    def cmd_hallo(self):
        return "Hallo!"

    def cmd_zeit(self):
        return "08:00"

b = Befehle()
for ein in ["hallo", "zeit", "rm"]:
    f = getattr(b, "cmd_" + ein, None)
    if callable(f):
        print(f())
    else:
        print("unbekannt:", ein)
# Hallo!
# 08:00
# unbekannt: rm

import inspect, sys

def test_plus():
    assert 1 + 1 == 2

def test_minus():
    assert 3 - 1 == 1

def hilfe(name, laut=False):
    pass

modul = sys.modules[__name__]
for name, f in inspect.getmembers(
        modul, inspect.isfunction):
    if name.startswith("test_"):
        try:
            f()
            print("OK  ", name)
        except AssertionError:
            print("FAIL", name)
print(inspect.signature(hilfe))
# FAIL test_minus
# OK   test_plus
# (name, laut=False)

